add("What is the time complexity of finding the maximum element in an unsorted array?",["O(1)","O(log n)","O(n)","O(n^2)"],"O(n)","Must check every element to find maximum, O(n).","Easy","DSA","practice");
add("What is the time complexity of reversing an array?",["O(1)","O(n)","O(n log n)","O(n^2)"],"O(n)","Each element is visited once during reversal.","Easy","DSA","practice");
add("What is the time complexity of counting occurrences of an element in a sorted array?",["O(n)","O(log n)","O(n log n)","O(1)"],"O(n)","Even in sorted array, you must scan for all occurrences. Binary search finds one, but counting all is O(n).","Medium","DSA","practice");
add("What is the time complexity of finding a pair with a given sum in a sorted array (two pointers)?",["O(n^2)","O(n)","O(log n)","O(n log n)"],"O(n)","Two pointers approach: start and end pointers move inward, O(n).","Medium","DSA","practice");
